  for(const key of ['rate','min','minQty','tax']){const value=$('#pe_'+key).value;p[key]=value===''&&['rate','tax'].includes(key)?null:Number(value);}if(pricingEdited&&p.rate!==null&&p.tax!==null)p.priceConfigured=true;
  const tiers=$('#pe_tiers').value.trim();p.tiers=tiers?tiers.split(',').map(s=>s.split(':').map(Number)):null;
