 p.compatibility=p.compatibility||[];if(can('pricing.manage'))p.charges=p.charges||[];
 DP.syncPhase2Rules(p);
 if(!p.name||!p.code){toast('Enter a product name and code.','er');return}
 const error=(can('pricing.view')||can('pricing.manage'))&&DP.pricingError?.({...DP.resolveProduct(p,currentTemplateSettings()),rate:p.rate??0,tax:p.tax??0,priceConfigured:p.on?p.priceConfigured:true});if(error){toast(error,'er');return}
