/* Catalog verification reads readiness/status/counts from the backend. */
let CATALOG_FILTER={q:'',category:'',status:'',template:'',page:1,pageSize:20},CATALOG_DATA=null,CATALOG_PLAN=null,CATALOG_REQUEST=0,CATALOG_SEARCH_TIMER=null;
V.catalog=()=>`<h1>Catalog Verification</h1><p class="mu">Compare actual catalog records with the documented SRS manifest. Configuration and pricing readiness are independent; verification never activates a product.</p><div class="row"><button class="b2" onclick="catalogTemplatesForm()">Manage catalog templates</button>${can('product.manage')&&can('pricing.manage')?'<button onclick="prepareCatalogPlan()">Review catalog configuration plan</button>':''}</div><div class="grid catalog-filters">${fld('Search required products',`<input value="${esc(CATALOG_FILTER.q)}" placeholder="Search by product name" oninput="searchCatalog(this.value)">`)}${fld('Catalog category',`<select onchange="setCatalogFilter('category',this.value)">${selectOptions(S.cats.map(c=>[c.id,c.name]),CATALOG_FILTER.category,'All categories')}</select>`)}${fld('Catalog status',`<select onchange="setCatalogFilter('status',this.value)">${selectOptions(['Missing','Inactive (Price Pending)','Inactive','Active','Conflict'],CATALOG_FILTER.status,'All statuses')}</select>`)}${fld('Assigned template',`<select onchange="setCatalogFilter('template',this.value)">${selectOptions(currentCatalogTemplates().map(t=>[t.id,t.name]),CATALOG_FILTER.template,'All templates')}</select>`)}${fld('Products per page',`<select onchange="setCatalogFilter('pageSize',Number(this.value))">${selectOptions([10,20,40,100],CATALOG_FILTER.pageSize)}</select>`)}</div><div id="catalog-counts" aria-live="polite"></div><div id="catalog-results" aria-live="polite"><p class="mu">Loading catalog verification…</p></div>`;
function searchCatalog(value){CATALOG_FILTER.q=value;CATALOG_FILTER.page=1;++CATALOG_REQUEST;clearTimeout(CATALOG_SEARCH_TIMER);CATALOG_SEARCH_TIMER=setTimeout(loadCatalogChecklist,250);}
function setCatalogFilter(key,value){clearTimeout(CATALOG_SEARCH_TIMER);CATALOG_FILTER[key]=value;CATALOG_FILTER.page=1;loadCatalogChecklist();}
function catalogPage(page){CATALOG_FILTER.page=page;loadCatalogChecklist();}
async function loadCatalogChecklist(){
 if(!can('product.manage')&&!can('pricing.manage'))return;
 const sequence=++CATALOG_REQUEST,query=new URLSearchParams();
 for(const [key,value] of Object.entries(CATALOG_FILTER))if(value!==''&&value!==undefined)query.set(key,String(value));
 const el=$('#catalog-results');if(!el)return;el.innerHTML='<p class="mu">Loading catalog verification…</p>';
 try{const data=await api('/api/catalog/checklist?'+query);if(sequence!==CATALOG_REQUEST||!$('#catalog-results'))return;CATALOG_DATA=data;renderCatalogChecklist();}
 catch(error){if(sequence!==CATALOG_REQUEST||!$('#catalog-results'))return;$('#catalog-counts').innerHTML='';$('#catalog-results').innerHTML=`<div class="note">${esc(error.message)} <button class="s b2" onclick="loadCatalogChecklist()">Retry catalog verification</button></div>`;}
}
function catalogReadiness(value){return typeof value==='string'?value:value?.status||'Pending';}
function catalogIssueText(value){return typeof value==='string'?value:value?.message||value?.reason||value?.code||'Requires review';}
function renderCatalogChecklist(){
 const data=CATALOG_DATA;if(!data||!$('#catalog-results'))return;
 const counts=data.counts||{},rows=data.rows||[],pagination=data.pagination||{page:data.page||1,pageSize:data.pageSize||20,total:data.filteredTotal??rows.length,totalPages:Math.max(1,Math.ceil((data.filteredTotal??rows.length)/(data.pageSize||20)))};
 $('#catalog-counts').innerHTML=`<div class="cards">${[['required','Required products'],['missing','Missing'],['inactive','Inactive'],['active','Active']].map(([key,label])=>`<div class="card"><b>${Number(counts[key]||0)}</b><span>${label}</span></div>`).join('')}</div><p class="mu">Totals cover the full required manifest, before search or filters.${data.coverage?.note||data.coverage?.source?' '+esc(data.coverage.note||data.coverage.source):''}</p>`;
 const rowHTML=rows.map(row=>{const details=[...(row.missingRequirements||[]),...(row.warnings||[])].map(catalogIssueText),configuration=catalogReadiness(row.configurationReadiness),pricing=catalogReadiness(row.pricingReadiness);return `<tr><td><b>${esc(row.name)}</b><br><span class="mu">${esc(row.code)}</span>${row.productId?`<br><span class="mu">${esc(row.productId)}</span>`:''}</td><td>${esc(row.categoryName||'Not assigned')}</td><td>${esc(row.templateName||'Not assigned')}</td><td>${esc(row.status)}</td><td>${esc(configuration)}</td><td>${esc(pricing)}</td><td>${details.length?`<ul>${[...new Set(details)].map(detail=>`<li>${esc(detail)}</li>`).join('')}</ul>`:'No missing requirements identified.'}${row.mappingReason?`<p class="mu">${esc(row.mappingReason)}</p>`:''}</td><td>${row.productId?`<button class="s b2" onclick="prodForm(${esc(JSON.stringify(row.productId))})">Review product</button>`:'Create through catalog plan'}</td></tr>`;}).join('');
 const total=Number(pagination.total??data.filteredTotal??rows.length),page=Number(pagination.page||1),totalPages=Math.max(1,Number(pagination.totalPages||1));
 $('#catalog-results').innerHTML=`<p class="mu">${total} matching required products.</p>${rows.length?`<div class="card tw"><table class="catalog-checklist" aria-label="Required catalog product verification"><thead><tr><th>Product Name</th><th>Category</th><th>Assigned Template</th><th>Catalog Status</th><th>Configuration Readiness</th><th>Pricing Readiness</th><th>Missing Requirements</th><th>Actions</th></tr></thead><tbody>${rowHTML}</tbody></table></div>`:'<div class="card"><p>No required products match these filters.</p><button class="s b2" onclick="resetCatalogFilters()">Clear filters</button></div>'}<div class="row"><button class="s b2" ${page<=1?'disabled':''} onclick="catalogPage(${page-1})">Previous catalog page</button><span>Page ${page} of ${totalPages}</span><button class="s b2" ${page>=totalPages?'disabled':''} onclick="catalogPage(${page+1})">Next catalog page</button></div>`;
}
function resetCatalogFilters(){CATALOG_FILTER={q:'',category:'',status:'',template:'',page:1,pageSize:20};render();}
async function prepareCatalogPlan(){
 if(busy||!can('product.manage')||!can('pricing.manage'))return;
 lock(true);try{
  CATALOG_PLAN=await api('/api/catalog/prepare',{method:'POST',body:JSON.stringify({revision:REV,apply:false})});
  const changes=CATALOG_PLAN.changes||[],issues=CATALOG_PLAN.issues||[];
  modal(`<h2>Catalog configuration plan</h2><p>Review the proposed missing records and template assignments. Existing IDs, approved rates, quotation snapshots and activation states are retained. New unpriced products stay inactive.</p><p><b>${changes.length}</b> proposed changes${issues.length?` · <b>${issues.length}</b> items require review`:''}.</p>${changes.length?`<div class="card tw"><table aria-label="Proposed catalog configuration"><tr><th>Product</th><th>Existing / proposed ID</th><th>Proposed change</th><th>Assigned template</th></tr>${changes.map(change=>`<tr><td>${esc(change.name||change.productName||Catalog.manifest.find(entry=>entry.code===change.code)?.name||change.code||'Catalog product')}<br><span class="mu">${esc(change.code||'')}</span></td><td>${esc(change.id||change.productId||'New record')}</td><td>${esc(change.action||change.type||'Prepare configuration')}</td><td>${esc(change.templateName||currentCatalogTemplates().find(template=>template.id===change.templateId)?.name||'Review assignment')}</td></tr>`).join('')}</table></div>`:'<p class="mu">No catalog changes are required.</p>'}${issues.length?`<div class="note"><ul>${issues.map(issue=>`<li>${issue.code?esc(issue.code)+': ':''}${esc(catalogIssueText(issue))}</li>`).join('')}</ul></div>`:''}<div class="row">${changes.length?'<button onclick="applyCatalogPlan()">Apply catalog configuration</button>':''}<button class="b2" onclick="closeM()">Close</button></div>`,900);
 }catch(error){failure(error,true);}finally{lock(false);}
}
async function applyCatalogPlan(){
 if(busy||!CATALOG_PLAN||!can('product.manage')||!can('pricing.manage'))return;
 lock(true);try{const result=await api('/api/catalog/prepare',{method:'POST',body:JSON.stringify({revision:CATALOG_PLAN.revision,apply:true})});adopt(result);CATALOG_PLAN=null;closeM();rebaseDraft();render();toast('Catalog configuration applied. Product activation and approved prices are retained.');}catch(error){failure(error,true);}finally{lock(false);}
}
const pricingView=V.price;
V.price=()=>{const raw=S.products;let html;try{S.products=raw.map(p=>DP.resolveProduct(p,currentTemplateSettings()));html=pricingView();}finally{S.products=raw;}return html.replace(/<summary><b>(.*?)<\/b>/g,(match,name)=>{const p=S.products.find(p=>esc(p.name)===name);return match+(p?` <button class="s b2" onclick="event.preventDefault();prodForm('${p.id}')">Edit specifications and rules</button>`:'')});};
async function op_(id,key,index,column,value){if(busy||!can('pricing.manage'))return;const p=effectiveProd(id),field=p.f.find(f=>f.k===key);if(!field?.o?.[index])return;field.o[index][column]=column===2?Number(value):value;Object.assign(prod(id),DP.stripProduct(p,currentTemplateSettings()));if(await persist())toast('Option price saved');}
