/* Dynamic configurator honours numeric and conditional field metadata. */
function sizeQuantityValue(values,key){return Object.prototype.hasOwnProperty.call(values,key)?values[key]:0;}
function sizeQuantityField(f){
 const values=CF[f.k]||{},sizes=(f.sizes||[]).filter(s=>s.enabled!==false),total=sizes.reduce((sum,s)=>sum+(Number.isInteger(sizeQuantityValue(values,s.key))?sizeQuantityValue(values,s.key):0),0);
 const unavailable=Object.keys(values).filter(key=>!sizes.some(s=>s.key===key));
 return `<div class="size-breakdown"><span>${esc(f.l)} (quantity is calculated)</span><div class="size-quantities">${sizes.map(s=>fld(s.label,`<input type="number" min="0" max="1000000" step="1" value="${esc(sizeQuantityValue(values,s.key)??0)}" oninput="setSizeQuantity(${esc(JSON.stringify(f.k))},${esc(JSON.stringify(s.key))},this.value)">`)).join('')}</div><p class="mu" data-size-total="${esc(f.k)}" aria-live="polite">Total Quantity: ${total}</p>${unavailable.length?`<div class="note">Previously selected sizes are unavailable: ${unavailable.map(esc).join(', ')}. <button class="s b2" onclick="clearUnavailableSizes(${esc(JSON.stringify(f.k))})">Clear unavailable quantities</button></div>`:''}</div>`;
}
function refreshSizeDependentFields(p){
 refreshConfigurationContainer('#config-fields',configurationFields(p));
}
function refreshConfigurationContainer(selector,html){
 const container=$(selector);if(!container)return;
 const active=document.activeElement,retained=active?.tagName==='INPUT'&&active.type==='number'?active.closest('[data-config-field]'):null;
 if(!retained||retained.parentElement!==container){if(container.innerHTML!==html)container.innerHTML=html;return;}
 // Keep the focused number control attached while conditional siblings change.
 // Replacing it during oninput interrupts multi-digit keyboard and mobile entry.
 const replacement=document.createElement('div');replacement.innerHTML=html;
 const children=Array.from(replacement.children),index=children.findIndex(child=>child.dataset.configField===retained.dataset.configField);
 if(index<0){container.innerHTML=html;return;}
 for(const child of Array.from(container.children))if(child!==retained)child.remove();
 for(const child of children.slice(0,index))container.insertBefore(child,retained);
 for(const child of children.slice(index+1))container.append(child);
}
function configurationQuantity(p){const fields=DP.sizeFields(p),legacy=fields.find(f=>f.legacy),html=legacy?sizeQuantityField(legacy):fields.some(f=>DP.fieldVisible(f,CF,p))||['fixed','package'].includes(p.m)?'':fld('Quantity',`<input type="number" min="${p.minQty||1}" value="${CF.qty}" oninput="cs_('qty',this.value)">`);return html.replace(/^<([a-z]+)/,'<$1 data-config-field="quantity"');}
