function clearUnavailableOptions(key){const p=effectiveProd(CF._p),f=p.f.find(f=>f.k===key),allowed=DP.availableOptions(p,f,CF).map(o=>o[0]);cs_(key,(Array.isArray(CF[key])?CF[key]:[]).filter(value=>allowed.includes(value)));if($('#config-fields'))$('#config-fields').innerHTML=configurationFields(p);}
function configurationForEditor(p,values,changedKey){const initial={...defCfg(p),...values},config=changedKey?DP.reconcileConfig(p,initial,changedKey):DP.normalizeConfig(p,initial);return {...DP.normalizeConfig(p,{...defCfg(p),...config}),_p:values._p||p.id,_i:values._i||''};}
function openCfg(pid,iid){
 const p=effectiveProd(pid);if(!p){toast('This product was removed; saved prices remain available.','wa');return}
 const item=iid?Q.items.find(i=>i.id===iid):null;CF=configurationForEditor(p,{...(item?clone(item.cfg):{}),_p:pid,_i:iid||''});
 const legacyPrint=item&&p.phase3LegacyFields?.find(f=>item.cfg[f.k]!==undefined);
 modal(`<h2>${esc(p.name)}</h2>${legacyPrint?`<p class="note">Saved ${esc(legacyPrint.l)}: ${esc(item.cfg[legacyPrint.k])}. Choose current named locations to update this item.</p>`:''}<p class="mu">${esc(p.description||'')} ${p.tiers?'Quantity tiers: '+p.tiers.map(t=>t[0]+'+ at '+inr(R(t[1]))).join(' · '):''}</p><div class="grid" id="config-quantity">${configurationQuantity(p)}</div><div class="grid" id="config-fields">${configurationFields(p)}</div><div id="cc" style="margin-top:14px"></div><button onclick="addItem()">${item?'Update item':'Add to quotation'}</button> <button class="b2" onclick="openCat()">Back</button>`,850);refCalc();
}
function cs_(key,value){CF[key]=['qty','w','h'].includes(key)?Number(value):value;const p=effectiveProd(CF._p);if(key==='printLocations')for(const field of p.phase3LegacyFields||[])delete CF[field.k];const before={...CF};CF=configurationForEditor(p,CF,key);const changed=(p.f||[]).filter(f=>f.k!==key&&before[f.k]!==undefined&&before[f.k]!==CF[f.k]).map(f=>f.l);if(changed.length)toast('Updated selections for compatibility: '+changed.join(', '));if(p.f.some(f=>f.k===key&&f.allowCustom)||(p.compatibility||[]).some(r=>r.when?.key===key||r.when?.conditions?.some(c=>c.key===key))||(p.f||[]).some(f=>f.when?.key===key||f.when?.conditions?.some(c=>c.key===key))){refreshConfigurationContainer('#config-fields',configurationFields(p));refreshConfigurationContainer('#config-quantity',configurationQuantity(p));}refCalc();}
function setSizeQuantity(key,size,value){CF[key]={...(CF[key]||{}),[size]:Number(value)};const p=effectiveProd(CF._p),f=DP.sizeFields(p).find(f=>f.k===key),total=(f?.sizes||[]).filter(s=>s.enabled!==false).reduce((sum,s)=>sum+(Number.isInteger(sizeQuantityValue(CF[key],s.key))?sizeQuantityValue(CF[key],s.key):0),0);CF.qty=total;CF=configurationForEditor(p,CF,'qty');const node=document.querySelector(`[data-size-total="${key}"]`);if(node)node.textContent='Total Quantity: '+total;if([...(p.f||[]),...(p.compatibility||[])].some(field=>field.when?.key==='qty'||field.when?.conditions?.some(c=>c.key==='qty')))refreshSizeDependentFields(p);refCalc();}
function clearUnavailableSizes(key){const p=effectiveProd(CF._p),f=DP.sizeFields(p).find(f=>f.k===key),allowed=(f?.sizes||[]).filter(s=>s.enabled!==false).map(s=>s.key);CF[key]=Object.fromEntries(Object.entries(CF[key]||{}).filter(([size])=>allowed.includes(size)));CF.qty=Object.values(CF[key]).reduce((sum,value)=>sum+(Number.isInteger(value)?value:0),0);CF=configurationForEditor(p,CF,'qty');if($('#config-fields'))$('#config-fields').innerHTML=configurationFields(p);if($('#config-quantity'))$('#config-quantity').innerHTML=configurationQuantity(p);refCalc();}
function refCalc(){const p=effectiveProd(CF._p),r=calc(p,CF);$('#cc').innerHTML=r.err?`<div class="note">${esc(r.err)}</div>`:`<div class="card"><table class="tot"><tr><td>Quantity</td><td class="n">${r.qty}</td></tr>${r.L.map(l=>`<tr><td>${esc(l[0])}</td><td class="n">${inr(l[1])}</td></tr>`).join('')}<tr><td>Taxable item amount</td><td class="n">${inr(r.taxable)}</td></tr><tr><td>GST ${r.tax}% ${r.taxMode==='inclusive'?'(included in price)':r.taxMode==='exempt'?'(exempt)':''}</td><td class="n">${inr(r.gst)}</td></tr><tr class="g"><td>Item total incl. GST</td><td class="n">${inr(r.grand)}</td></tr></table><p class="mu">${r.sp.map(esc).join(' · ')}. Discount is applied at quotation level.</p></div>`;}
function addItem(){const p=effectiveProd(CF._p),old=Q.items.find(x=>x.id===CF._i),it=mkItem(p,CF,CF._i,old&&old.notes);if(!it){toast(calc(p,CF).err,'er');return}if(old)Q.items[Q.items.indexOf(old)]=it;else Q.items.push(it);closeM();upd();toast('Item '+(old?'updated':'added'))}
function refreshP(){ask('Recalculate every item using the CURRENT catalog prices? Original quoted prices on this quotation will be replaced.',()=>{Q._refreshPrices=true;Q.items=Q.items.map(i=>{const p=effectiveProd(i.pid);return(p&&mkItem(p,i.cfg,i.id,i.notes))||i});upd();toast('Prices refreshed from catalog','wa')})}
function sumHTML(q){let t;try{t=tot(q)}catch(e){return `<div class="note">${esc(e.message)}</div>`}const row=(label,amount,cls='')=>`<tr class="${cls}"><td>${label}</td><td class="n">${amount}</td></tr>`;return `<div class="mu">Items: ${t.n} · Total quantity: ${t.qty}</div><table class="tot" style="max-width:480px;margin-left:auto">${row('Product base amounts',inr(t.ib))}${row('Item-level charges',inr(t.ic))}${row('Delivery and other charges',inr(t.qc))}${row('Discount','− '+inr(t.disc))}${row('Taxable amount',inr(t.taxable))}${t.br.map(b=>row(t.taxDisplay==='igst'?`IGST ${b.r}% on ${inr(b.t)}`:`CGST ${b.r/2}% + SGST ${b.r/2}% on ${inr(b.t)}`,inr(b.x))).join('')}${row('Grand total',inr(t.grand),'g')}</table>`;}
const basicItemRows=itemsHTML;
itemsHTML=()=>{let html=basicItemRows();if(can('pricing.override'))for(const item of Q.items)html=html.replace(`onclick="noteItem('${item.id}')">Note</button>`,`onclick="noteItem('${item.id}')">Note</button> <button class="s b2" onclick="overrideItem('${item.id}')">Price override</button>`);return html;};
function overrideItem(id){if(!can('pricing.override'))return;const item=Q.items.find(i=>i.id===id);modal(`<h2>Authorized price override</h2><p class="mu">${esc(item.name)}. This adjustment is recorded with your identity and reason when saved.</p>${fld('Item subtotal before tax treatment (₹)',`<input id="override_amount" type="number" min="0" step="0.01" value="${item.sub/100}">`)}${fld('Reason (required)',`<textarea id="override_reason">${esc(item.override?.reason||'')}</textarea>`)}<br><button onclick="applyOverride('${id}')">Apply override</button>`,550);}
function applyOverride(id){const item=Q.items.find(i=>i.id===id),amount=Number($('#override_amount').value),reason=$('#override_reason').value.trim();if(!Number.isFinite(amount)||amount<0||!reason){toast('Enter a non-negative amount and a reason.','er');return}const originalSub=item.override?.originalSub??item.sub,originalBase=item.override?.originalBase??item.base,originalLines=clone(item.override?.originalLines??item.L);item.override={amount,reason,originalSub,originalBase,originalLines};item.sub=R(amount);item.base=Math.min(originalBase,item.sub);item.L=[...originalLines,['Authorized price adjustment',item.sub-originalSub]];closeM();upd();toast('Price override ready; save the quotation to record it.');}

/* Settings and dedicated user management. */
const baseSettings=V.set;
V.set=()=>{
 let html=baseSettings();
 html=html.replace(/<label class="checkbox"><input type="checkbox"[^>]*onchange="SETD.showNotes=this.checked"> Show internal item notes on customer PDFs<\/label>/,'<p class="mu">Internal item notes are excluded from customer documents.</p>');
 const field=(k,label,type='text')=>fld(label,`<input type="${type}" value="${esc(SETD[k]??'')}" oninput="SETD.${k}=${type==='number'?'Number(this.value)':'this.value'}">`);
 html+=`<div class="card"><h2>Quotation presentation and authorization</h2><div class="grid">${field('signature','Authorized signatory')}${field('footer','PDF footer')}${field('customerNotes','Customer-facing notes')}${field('sequenceStart','Next sequence minimum','number')}${field('employeeDiscountLimit','Employee discount limit (%)','number')}${field('employeeDiscountMax','Employee fixed discount cap (₹; 0 = percentage cap only)','number')}${fld('Tax display',`<select onchange="SETD.taxDisplay=this.value">${selectOptions([['split','CGST + SGST'],['igst','IGST']],SETD.taxDisplay||'split')}</select>`)}${fld('Default tax treatment',`<select onchange="SETD.taxMode=this.value">${selectOptions([['exclusive','Tax exclusive'],['inclusive','Tax inclusive'],['exempt','Exempt']],SETD.taxMode||'exclusive')}</select>`)}${fld('Currency','<input readonly value="INR (Indian rupees)">')}${fld('Company logo (PNG/JPEG)',`<input type="file" accept="image/png,image/jpeg" onchange="readCompanyLogo(this.files[0])">`)}</div>${SETD.logo?'<p class="mu">Company logo configured. <button class="s b2" onclick="SETD.logo=\'\';render()">Remove logo</button></p>':''}<label class="checkbox"><input type="checkbox" ${SETD.allowAdditionalCharges!==false?'checked':''} onchange="SETD.allowAdditionalCharges=this.checked"> Allow employees to add quotation-level charges</label><label class="checkbox"><input type="checkbox" ${SETD.independentApproval!==false?'checked':''} onchange="SETD.independentApproval=this.checked"> Require independent internal approval</label><button onclick="saveSettings()">Save settings</button></div><div class="card"><h2>WhatsApp settings</h2><p class="note">Integration: manual click-to-chat. Staff download the protected PDF and attach it in WhatsApp. Delivery and read status are unavailable. Automated document delivery requires a separately configured WhatsApp Business provider.</p><div id="wa-settings">Loading WhatsApp settings?</div><p class="mu">Available message fields: {{customer_name}}, {{company_name}}, {{quotation_number}}, {{quotation_date}}, {{grand_total}}, {{valid_until}}.</p></div>`;
 return html;
};
async function readCompanyLogo(file){if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>300000){toast('Choose a PNG or JPEG up to 300 KB.','er');return}const reader=new FileReader();reader.onload=()=>{SETD.logo=reader.result;toast('Logo selected; save settings to apply.')};reader.readAsDataURL(file);}
V.team=()=>`<h1>User Management</h1><div class="card"><div class="row spread"><p class="mu">Manage employee access and account status.</p><button onclick="userForm()">+ Add team member</button></div><div id="team-list" class="tw">Loading team members…</div></div>`;
let PERMISSION_CATALOG=null;
const originalEditUser=editUser;
editUser = async function(id){
 originalEditUser(id);try{if(!PERMISSION_CATALOG)PERMISSION_CATALOG=await api('/api/permissions');const u=TEAM.find(u=>u.id===id);const form=$('#modal form');if(form){const container=document.createElement('div');container.innerHTML=`<details><summary>Employee permissions</summary><p class="mu">Choose role defaults or an explicit permission set. Administrator access remains unrestricted.</p><label class="checkbox"><input id="permission_defaults" type="checkbox" ${u.permissionOverrides==null?'checked':''}> Use employee role defaults</label><div class="permission-grid">${PERMISSION_CATALOG.permissions.map(p=>`<label class="checkbox"><input type="checkbox" data-permission="${esc(p)}" ${(u.permissions||[]).includes(p)?'checked':''}>${esc(p)}</label>`).join('')}</div></details>`;form.append(container)}}catch(e){toast(e.message,'er')}
}
const originalSaveUser=saveUser;
saveUser = async function(id,version){
 if(!$('#permission_defaults'))return originalSaveUser(id,version);
 if(busy)return;const data={version,name:$('#edit_user_name').value,username:$('#edit_user_username').value,role:$('#edit_user_role').value,active:$('#edit_user_active').checked,permissions:$('#permission_defaults').checked?null:[...document.querySelectorAll('[data-permission]:checked')].map(el=>el.dataset.permission)};
 lock(true);try{await api('/api/users/'+id,{method:'PATCH',body:JSON.stringify(data)});closeM();await loadTeam();toast('Account permissions updated');if(id===AUTH.id){AUTH=null;CSRF=null;render()}}catch(e){failure(e)}finally{lock(false)}
}

/* Quotation previews never expose internal notes. */
const baseDocHTML=docHTML;
docHTML = function(q){
 const safe=clone(q);if(q.contact)safe.customerSnapshot={...(q.customerSnapshot||cust(q.cid)),...q.contact};for(const i of safe.items){i.notes='';i.sp=DP.customerSpecifications(i);}let html=baseDocHTML(safe);const company=DP.companyDetails(q.companySnapshot||S.set);
 if(company.logo&&/^data:image\/(png|jpeg);base64,/.test(company.logo))html=html.replace('<div class="hd">',`<div class="hd"><img alt="Company logo" src="${esc(company.logo)}" style="max-width:70px;max-height:55px;object-fit:contain">`);
 if(q.ref||q.req)html=html.replace('<div class="tw">',`<p>${q.ref?'Reference: '+esc(q.ref)+'<br>':''}${q.req?'Requirements: '+esc(q.req):''}</p><div class="tw">`);
 html=html.replace('Authorized Signatory',esc(company.signature||'Authorized Signatory'));
 if(company.customerNotes||company.footer)html=html.replace('</ol>',`</ol><p>${esc(company.customerNotes||'')}</p><p class="mu">${esc(company.footer||'')}</p>`);
 return html;
}
const originalViewQ=viewQ,originalPreview=prevQ,originalNewView=V.new;
viewQ = function(id){originalViewQ(id);const box=$('#modal .box');if(box){box.insertAdjacentHTML('beforeend',`<div class="row noprint">${shareButton(id)} <button class="s b2" onclick="quotationHistory('${id}')">Sharing history</button></div>`);}}
prevQ = function(){originalPreview();const box=$('#modal .box');if(box)box.insertAdjacentHTML('beforeend',`<div class="row noprint">${shareButton(Q.id)}</div>`);}
V.new=()=>originalNewView()+`<div class="row">${shareButton(Q?.id)}</div>`;
function statusQ(id){const q=getQ(id);modal(`<h2>Change status — ${esc(q.no)}</h2><p class="mu">Customer approval is recorded separately from sharing. ${S.set.independentApproval!==false?'Independent internal approval is required.':''}</p>${fld('New status',`<select id="ns">${selectOptions(ST.filter(s=>s!=='Approved Internally'||can('quotation.approve')||s===q.status),q.status)}</select>`)}${fld('Remarks','<textarea id="status-remarks" rows="3"></textarea>')}<br><button onclick="setSt('${id}')">Update status</button>`,520);}
async function setSt(id){if(busy)return;const q=getQ(id);const status=$('#ns').value;if(status===q.status){closeM();return}lock(true);try{const record=await api('/api/quotations/'+id);await api('/api/quotations/'+id+'/status',{method:'POST',body:JSON.stringify({version:record.version,status,remarks:$('#status-remarks').value})});adopt(await api('/api/state'));closeM();rebaseDraft();render();toast('Status updated')}catch(e){failure(e)}finally{lock(false)}}

/* Report filtering matches server CSV exports. */
const originalReportView=V.rep;
V.rep=()=>originalReportView().replace('<div id="server-reports"',`<div class="row">${fld('Employee',`<select onchange="RF.sp=this.value;refreshReports()">${selectOptions(employeeOptions(),RF.sp,'All permitted employees')}</select>`)}${fld('Customer',`<select onchange="RF.cu=this.value;refreshReports()">${selectOptions(S.customers.map(c=>[c.id,c.name]),RF.cu,'All customers')}</select>`)}${fld('Status',`<select onchange="RF.st=this.value;refreshReports()">${selectOptions(ST,RF.st,'All statuses')}</select>`)}</div><div class="card"><h2>WhatsApp sharing report</h2><div id="report-wa">Loading…</div></div><div id="server-reports"`);
function repCsv(){return downloadApi('/api/reports/quotations.csv?'+reportQuery(),'quotation-report.csv');}

/* Manual sharing is a reviewable handoff, with explicit confirmation and retries. */
const defaultWhatsAppTemplate='Hello {{customer_name}},\nGreetings from {{company_name}}.\nPlease find quotation {{quotation_number}} dated {{quotation_date}} for {{grand_total}}.\nValid until: {{valid_until}}.\nPlease review and contact us with any questions.\nThank you.';
let WA_PREPARED=null,WA_HISTORY=[],WA_SETTINGS=null,WA_QUOTATION=null;
const WF={q:'',status:'',from:'',to:''};
function defaultMessage(q){const c=q.customerSnapshot||cust(q.cid),s=DP.companyDetails(q.companySnapshot||S.set),values={customer_name:c.name,company_name:s.name,quotation_number:q.no,quotation_date:fd(q.date),grand_total:inr(tot(q).grand),valid_until:fd(q.valid)};return (WA_SETTINGS?.data?.messageTemplate||S.set.whatsappTemplate||defaultWhatsAppTemplate).replace(/\{\{(\w+)\}\}|\{(\w+)\}/g,(all,snake,camel)=>{const aliases={customerName:'customer_name',companyName:'company_name',quotationNumber:'quotation_number',quotationDate:'quotation_date',total:'grand_total',validUntil:'valid_until'};return values[snake||aliases[camel]]??all});}
async function shareQuotation(id){
 if(busy||!can('quotation.share_whatsapp'))return;
 if(!id||(location.hash==='#new'&&Q?.id===id)){if(!Q||!okQ(true)||!await saveQ(false))return;id=Q.id}
 lock(true);
 try{
 WA_SETTINGS=await api('/api/whatsapp/settings');
 const record=await api('/api/quotations/'+encodeURIComponent(id)),q=record.data;
 WA_QUOTATION={id:q.id,version:record.version};WA_PREPARED=null;
 const c=cust(q.cid),number=q.contact?.wa??c.wa??q.customerSnapshot?.wa??'';
 modal(`<h2>Share on WhatsApp — ${esc(q.no)}</h2><p class="note">Manual sharing: review the number and message, then open WhatsApp. Download the PDF and attach it in the chat. Delivery and reading cannot be verified.</p>${!number?'<p class="note">Add the customer’s WhatsApp number with its country code to continue.</p>':''}<div class="grid">${fld('WhatsApp number (country code required)',`<input id="wa_number" type="tel" autocomplete="tel" value="${esc(number)}" placeholder="+919876543210">`)}${fld('Message',`<textarea id="wa_message" maxlength="4000" rows="7">${esc(defaultMessage(q))}</textarea>`)}</div>${can('customer.edit')?'<label class="checkbox"><input type="checkbox" id="wa_save_number"> Save this WhatsApp number to the customer</label>':''}<br><button onclick="prepareWhatsApp('${id}')">Prepare PDF and WhatsApp chat</button><div id="wa-result" aria-live="polite"></div>`,760);
 }catch(e){failure(e)}finally{lock(false)}
}
async function prepareWhatsApp(id){
 if(busy)return;const number=$('#wa_number').value.trim().replace(/[ ()-]/g,''),message=$('#wa_message').value.trim();
 if(!/^\+[1-9]\d{7,14}$/.test(number)){toast('Enter an international WhatsApp number beginning with + and country code.','er');return}
 if(!message){toast('Enter a message before opening WhatsApp.','er');return}
 if(WA_QUOTATION?.id!==id){toast('Reopen this quotation to prepare sharing.','er');return}
 const q=getQ(id);if(!q)return;const saveNumber=Boolean($('#wa_save_number')?.checked);
 lock(true);try{
  const result=await api('/api/quotations/'+id+'/whatsapp',{method:'POST',body:JSON.stringify({version:WA_QUOTATION.version,number,message,saveNumber})});WA_PREPARED=result;invalidateSharingHistory();
  const el=$('#wa-result');if(el)el.innerHTML=`<div class="card" style="margin-top:18px"><h2>Ready for manual sharing</h2><ol><li><button class="s b2" onclick="downloadApi(WA_PREPARED.pdfUrl,'${esc(q.no.replace(/[^A-Za-z0-9_-]/g,'-'))}.pdf')">Download quotation PDF</button></li><li><a class="button-link" href="${esc(result.clickToChatUrl)}" target="_blank" rel="noopener noreferrer">Open WhatsApp with reviewed message</a></li><li>Attach the downloaded PDF in WhatsApp and send.</li></ol><p class="mu">Opening the chat does not send the message. Only confirm after you manually send it.</p><button onclick="confirmManualShare('${result.data.id}')">I attached and sent the PDF</button> <button class="b2" onclick="markShareFailed('${result.data.id}')">Record a failed attempt</button></div>`;
  if(saveNumber)try{adopt(await api('/api/state'))}catch(e){status('error','Sharing is prepared. Reload the workspace before making further changes.')}
 }catch(e){failure(e)}finally{lock(false)}
}
async function confirmManualShare(id){return updateShareStatus(id,'Manually Confirmed','Employee confirmed attaching and sending the quotation PDF.');}
async function markShareFailed(id){return updateShareStatus(id,'Failed','Employee reported a manual sharing failure.');}
async function updateShareStatus(id,status,notes){if(busy)return;lock(true);try{await api('/api/whatsapp/history/'+id+'/status',{method:'POST',body:JSON.stringify({status,notes})});invalidateSharingHistory();closeM();render();toast('Sharing history updated. Quotation status is unchanged.')}catch(e){failure(e)}finally{lock(false)}}
function historyRows(rows,actions=true){return rows.length?`<div class="tw"><table><tr><th>Date/time</th><th>Quotation</th><th>Customer</th><th>WhatsApp number</th><th>Shared by</th><th>Type</th><th>Status</th><th>Provider ID</th>${actions?'<th>Actions</th>':''}</tr>${rows.map(r=>`<tr><td>${esc(new Date(r.createdAt).toLocaleString('en-IN'))}</td><td>${esc(r.quotationNumber||r.quotationId)}</td><td>${esc(r.customerName||'')}</td><td>${esc(r.recipientNumber||r.number||'')}</td><td>${esc(r.actorName||r.initiatedByName||r.initiatedBy||'')}</td><td>Quotation PDF</td><td>${bg(r.status)}</td><td>${esc(r.providerMessageId||'—')}</td>${actions?`<td><button class="s b2" onclick="shareDetails('${r.id}')">Details</button>${r.status==='Failed'?` <button class="s b2" onclick="retryShare('${r.id}')">Retry</button>`:''}</td>`:''}</tr>`).join('')}</table></div>`:'<p class="mu">No sharing attempts match these filters.</p>';}
V.wa=()=>`<h1>WhatsApp Sharing History</h1><p class="note">Prepared means the PDF and chat were prepared. Manually Confirmed is a staff confirmation; delivery and read status are unavailable.</p><div class="row">${fld('Search quotation, customer or number',`<input value="${esc(WF.q)}" oninput="WF.q=this.value;renderHistory()">`)}${fld('Sharing status',`<select onchange="WF.status=this.value;renderHistory()">${selectOptions(['Prepared','Manually Confirmed','Failed'],WF.status,'All statuses')}</select>`)}${fld('From date',`<input type="date" value="${WF.from}" onchange="WF.from=this.value;renderHistory()">`)}${fld('To date',`<input type="date" value="${WF.to}" onchange="WF.to=this.value;renderHistory()">`)}</div><div id="wa-history" aria-live="polite">Loading sharing history…</div>`;
function renderHistory(){const el=$('#wa-history');if(el)el.innerHTML=historyRows(WA_HISTORY.filter(r=>(!WF.q||JSON.stringify(r).toLowerCase().includes(WF.q.toLowerCase()))&&(!WF.status||r.status===WF.status)&&(!WF.from||r.createdAt.slice(0,10)>=WF.from)&&(!WF.to||r.createdAt.slice(0,10)<=WF.to)));}
async function allSharingHistory(query=''){const rows=[];let page=1,totalPages=1;do{const result=await api('/api/whatsapp/history?'+query+(query?'&':'')+'pageSize=100&page='+page);rows.push(...(result.data||[]));totalPages=result.pagination?.totalPages||1;page++}while(page<=totalPages);return rows;}
const sharingHistoryCache=new Map(),uncachedSharingHistory=allSharingHistory;
function invalidateSharingHistory(){sharingHistoryCache.clear()}
allSharingHistory=function(query=''){
 const key=AUTH?.id+'|'+query,previous=sharingHistoryCache.get(key);
 if(previous&&Date.now()-previous.at<20000)return previous.promise;
 const promise=uncachedSharingHistory(query).catch(error=>{sharingHistoryCache.delete(key);throw error});
 sharingHistoryCache.set(key,{at:Date.now(),promise});return promise;
};
async function loadWhatsAppHistory(){try{WA_HISTORY=await allSharingHistory();renderHistory()}catch(e){if($('#wa-history'))$('#wa-history').textContent=e.message}}
function shareDetails(id){const r=WA_HISTORY.find(r=>r.id===id);if(!r)return;modal(`<h2>Sharing attempt</h2><p>${esc(r.quotationNumber)} · ${bg(r.status)}</p><p>Recipient: ${esc(r.recipientNumber||r.number)}<br>Provider message ID: ${esc(r.providerMessageId||'Not available for manual sharing')}</p><pre class="message-preview">${esc(r.message||'')}</pre><p>${esc(r.errorDescription||r.notes||'')}</p>`,680);}
async function retryShare(id){const entry=WA_HISTORY.find(r=>r.id===id);if(!entry||busy)return;lock(true);try{const record=await api('/api/quotations/'+entry.quotationId);WA_PREPARED=await api('/api/whatsapp/history/'+id+'/retry',{method:'POST',body:JSON.stringify({version:record.version})});modal(`<h2>Retry prepared</h2><p class="note">Review the message and attach the quotation PDF manually in WhatsApp. Delivery is unverified.</p><pre class="message-preview">${esc(WA_PREPARED.data.message)}</pre><div class="row"><button onclick="downloadApi(WA_PREPARED.pdfUrl,'quotation.pdf')">Download PDF</button><a href="${esc(WA_PREPARED.clickToChatUrl)}" target="_blank" rel="noopener noreferrer">Open WhatsApp</a><button onclick="confirmManualShare('${WA_PREPARED.data.id}')">I attached and sent the PDF</button><button class="b2" onclick="markShareFailed('${WA_PREPARED.data.id}')">Record a failed attempt</button></div>`,700);await loadWhatsAppHistory()}catch(e){failure(e)}finally{lock(false)}}
async function quotationHistory(id){modal(`<h2>Quotation sharing history</h2><div id="quote-wa">Loading…</div>`,1000);try{const rows=await allSharingHistory('quotationId='+id);if($('#quote-wa'))$('#quote-wa').innerHTML=historyRows(rows,false)}catch(e){if($('#quote-wa'))$('#quote-wa').textContent=e.message}}
async function loadSrsView(view){
 if(view==='catalog')loadCatalogChecklist();if(view==='team')loadTeam();if(view==='wa')loadWhatsAppHistory();if(view==='set')loadWhatsAppSettings();
 if(['dash','rep'].includes(view)&&!(view==='dash'&&typeof loadDashboard==='function')&&can('quotation.share_whatsapp'))try{const rows=await allSharingHistory();const el=$(view==='dash'?'#dash-wa':'#report-wa');if(el){const permittedQuotes=new Set((view==='dash'?inRange():S.quotes.filter(q=>(!RF.a||q.date>=RF.a)&&(!RF.b||q.date<=RF.b)&&(!RF.sp||(q.createdBy||q.by)===RF.sp)&&(!RF.cu||q.cid===RF.cu)&&(!RF.st||q.status===RF.st))).map(q=>q.id));const filtered=rows.filter(r=>permittedQuotes.has(r.quotationId));el.innerHTML=view==='dash'?historyRows(filtered.slice(0,5),false):`<p>${filtered.length} attempts · ${filtered.filter(r=>r.status==='Failed').length} failed · ${filtered.filter(r=>r.status==='Manually Confirmed').length} manually confirmed</p>`+historyRows(filtered,false)}}catch(e){const el=$(view==='dash'?'#dash-wa':'#report-wa');if(el)el.textContent=e.message}
}
async function loadWhatsAppSettings(){try{WA_SETTINGS=await api('/api/whatsapp/settings');const el=$('#wa-settings');if(el)el.innerHTML=`<label class="checkbox"><input type="checkbox" id="wa_enabled" ${WA_SETTINGS.data.enabled?'checked':''}> Enable manual WhatsApp sharing</label>${fld('Default message template',`<textarea id="wa_template" rows="6">${esc(WA_SETTINGS.data.messageTemplate)}</textarea>`)}<br><button onclick="saveWhatsAppSettings()">Save WhatsApp settings</button>`}catch(e){if($('#wa-settings'))$('#wa-settings').textContent=e.message}}
async function saveWhatsAppSettings(){if(busy||!WA_SETTINGS)return;lock(true);try{WA_SETTINGS=await api('/api/whatsapp/settings',{method:'PATCH',body:JSON.stringify({version:WA_SETTINGS.version,enabled:$('#wa_enabled').checked,messageTemplate:$('#wa_template').value,mode:'manual'})});toast('WhatsApp settings saved')}catch(e){failure(e)}finally{lock(false)}}
// Finish loading every presentation module before the first authenticated render.
document.addEventListener('DOMContentLoaded', start, { once: true });
